    // named places ({ n: HUD label, d: metres after the start line, say: the commentator's lines; spelt so an English voice says them right)
    names: [
      {"n":"Medvode","d":196.0,"say":["Under the main road bridge, into Med-voh-deh!","Through the middle of Med-voh-deh, the river Sora on the right!"]},
      {"n":"Krožišče · Medvode","d":343.0,"say":["Into the roundabout! All the way round to the third exit!","Round the roundabout, three quarters of the way!"]},
      {"n":"Gorenjska cesta","d":601.0,"say":["Merging onto the main road, up the hill!","Onto the main road now, and it climbs!"]},
      {"n":"Na klancu","d":976.0,"say":["Na Klantsu! Past the big roundabout on the slip lane!","The big roundabout on the left, straight on along the slip lane!"]},
      {"n":"Zbiljska cesta","d":1111.0,"say":["Down the long straight towards Zbeel-yeh!","Houses either side, flat out to Zbeel-yeh!"]},
      {"n":"Zbiljski gaj","d":1461.0,"say":["Through the little wood of Zbeel-yeh!","Into the trees!"]},
      {"n":"Zbilje","d":2141.0,"say":["Zbeel-yeh, and another roundabout! First exit!","The roundabout at Zbeel-yeh, keep it tight!"]},
      {"n":"Zbiljsko jezero","d":2711.0,"say":["Along the lake! The boats are out today!","Past the lake of Zbeel-yeh, what a view!"]},
      {"n":"Most čez Savo","d":3531.0,"say":["Onto the long bridge over the Sava!","Over the river Sava, three hundred metres of bridge!"]},
      {"n":"Krožišče · Smlednik","d":4046.0,"say":["Roundabout at Smled-neek, straight across!","Straight over the roundabout!"]},
      {"n":"Valburga","d":4431.0,"say":["Through Valboorga!","Valboorga, past the church and the bus stop!"]},
      {"n":"Smlednik","d":4716.0,"say":["Right turn in Smled-neek, off the main road!","Hard right in Smled-neek, up towards the castle!"]},
      {"n":"Smledniški hrib","d":5291.0,"say":["Up the castle hill! Narrow and steep!","The road to the castle, one car wide!"]},
      {"n":"Stari grad · 504 m","d":6209.1,"say":["Up at the old castle of Smled-neek!","The castle ruins at the top of the hill!"]},
    ],
    // the commentator's own lines on this road (Comm: instead of Vršič's)
    comm: {
      introPass: ["Welcome to {track}! Thirteen cars, six kilometres of real road from the football ground to the castle, and you start {grid}.", "Here we are in Med-voh-deh, by the football ground. Roundabouts, a bridge and a castle hill ahead, and you line up {grid}.", "Welcome to {track}! Three roundabouts, the lake, the Sava and the castle road, and you start {grid}."],
      goPass: ["Lights out, and away they go, towards the roundabout!", "And they're off, down Medvoška street!", "Green light! Six kilometres to the castle!", "Go, go, go! Next stop, the old castle!"],
      introPassTT: ["Welcome to {track}! Six kilometres to the castle, just you and the clock.", "Here we are in Med-voh-deh. {cps} checkpoints between you and the castle.", "Welcome to {track}! No rivals this time, only the clock, the roundabouts and the hill."],
      goPassTT: ["Green light! The clock is running!", "Go! Mind the roundabout!", "And you're away, towards Zbeel-yeh!"],
      introTraffic: ["Welcome to {track}, and the roads are open today: cars, buses and bikes both ways. Just you and {rival}, first to the castle wins!", "Here we are in Med-voh-deh. A duel with {rival} through the traffic, round the roundabouts and over the Sava!", "Welcome to {track}! The buses stop where they stop. Beat {rival} to the castle!"],
      introPolice: ["Welcome to {track}! The police want a word with you, and they are right behind. Get to the castle without getting caught!", "Here we are in Med-voh-deh, and the blue lights are already flashing. Six kilometres to the castle. Do not stop!", "Welcome to {track}! A patrol car on your tail through the villages and over the bridge. Run for it!"],
      escaped: ["You made it to the castle! The police will have to wait for another day!", "Escaped! Up the castle hill and away!", "What a getaway, roundabouts and all!"],
      summitRecord: ["At the castle! A new personal best, {time}!", "Record run! {time} to the castle!", "What a drive! New personal best, {time}!"],
      summitEven: ["At the castle in {time}. That is your record to the thousandth!", "{time} at the castle, dead level with your best!"],
      summit: ["At the castle in {time}, {delta} seconds off your best.", "Across the line at the castle. {time}, just {delta} short of the record.", "That's the castle. {time}. {delta} seconds to find next time."],
    },
